#!/usr/bin/env node
// =============================================================================
// brief.mjs — render media-brief/PROMPTS.md from media-brief/shots.json
// -----------------------------------------------------------------------------
// The prompts are data. shots.json is the one place a prompt is written; this
// renders the copy and paste sheet a person works from, with the house style
// already joined onto each prompt so nothing has to be assembled by hand.
// brief.test.js fails when the sheet is out of date, the same way the other
// generated files in this repository are kept honest.
//
//   node scripts/media/brief.mjs          write PROMPTS.md
//   node scripts/media/brief.mjs --check  exit 1 if PROMPTS.md is stale
// =============================================================================

import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const dir = resolve(here, '..', '..', 'media-brief');

export function fullPrompt(brief, shot) {
  // A still names its look. `still` is the dark infrastructure set, `scene` the
  // daylight industry set. One look per page family, never mixed on a page.
  if (shot.mode === 'text-to-image') return `${shot.prompt} ${brief.style[shot.style ?? 'still']}`;
  if (shot.mode === 'image-to-image') return `${shot.prompt} ${brief.style.edit} ${brief.style.still}`;
  if (shot.mode === 'text-to-video') return `${shot.prompt} ${brief.style.video_from_text}`;
  return `${shot.prompt} ${brief.style.video}`;
}

const sourceLabel = (brief, s) =>
  []
    .concat(s)
    .map((x) => (brief.shots.some((o) => o.id === x) ? `the approved result of ${x}` : `\`site/${x}\``))
    .join(' and ');

export function render(brief) {
  const out = [];
  const push = (...l) => out.push(...l);
  push(
    '# Prompts',
    '',
    '<!-- Generated by scripts/media/brief.mjs from shots.json. Edit shots.json, then run the script. -->',
    '',
    `Written for Grok Imagine: \`${brief.models.image}\` for stills and edits, \`${brief.models.video}\` for video. Limits and model names were checked on ${brief.checked} against the sources at the end. Check them again before a batch, they move.`,
    '',
    'Every prompt below is complete: the house style is already joined on. Paste it as is. The rules in README.md apply to every one of them.',
    ''
  );
  const modes = [
    ['text-to-image', 'Stills, from text', `Aspect ratio and resolution are set in the interface or the API (\`aspect_ratio\`, \`resolution\`), not in the prompt. Ask for ${Math.min(4, brief.limits.images_per_request)} at a time and pick one.`],
    ['image-to-image', 'Stills, from one of our own frames', `Upload the source image with the prompt. The procedural frames fix the composition, so the result drops into the slot the loop already holds. Up to ${brief.limits.edit_source_images} source images per edit.`],
    ['text-to-video', 'Video, from text', `For a picture we have no still of. There is no source image to hold the look, so the house style is joined onto the prompt in words, and the prompt is longer than an image to video prompt is allowed to be. Expect to throw more of these away. Up to ${brief.limits.video_seconds_max} seconds at ${brief.limits.video_resolution}.`],
    ['image-to-video', 'Video, from an approved still', `Upload the approved still with the prompt. Keep the prompt short: the model can see the picture, and words that describe it again only add noise. Motion first, then the camera. One camera path. Up to ${brief.limits.video_seconds_max} seconds at ${brief.limits.video_resolution}. The site plays every clip muted and the encoder strips audio.`]
  ];
  for (const [mode, heading, note] of modes) {
    push(`## ${heading}`, '', note, '');
    for (const s of brief.shots.filter((x) => x.mode === mode)) {
      push(`### ${s.id} · \`${s.slot}\``, '');
      const facts = [];
      if (s.source) facts.push(`Source: ${sourceLabel(brief, s.source)}`);
      facts.push(`Aspect ${s.aspect}`);
      if (s.resolution) facts.push(`resolution ${s.resolution}`);
      if (s.seconds) facts.push(`${s.seconds} seconds`);
      if (s.pages) facts.push(`for ${s.pages.join(', ')}`);
      push(facts.join(' · '), '', '```text', fullPrompt(brief, s), '```', '', `Keep it if: ${s.keep}`, '', `Alt text: ${s.alt}`, '');
    }
  }
  push('## Never', '', ...brief.never.map((n) => `- ${n}`), '', '## Sources', '', ...brief.sources.map((u) => `- ${u}`), '');
  return out.join('\n');
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const brief = JSON.parse(readFileSync(resolve(dir, 'shots.json'), 'utf8'));
  const text = render(brief);
  const target = resolve(dir, 'PROMPTS.md');
  if (process.argv.includes('--check')) {
    const current = readFileSync(target, 'utf8').replace(/\r\n/g, '\n');
    if (current !== text) {
      console.error('brief: media-brief/PROMPTS.md is stale. Run node scripts/media/brief.mjs');
      process.exit(1);
    }
    console.log('brief: PROMPTS.md is current');
  } else {
    writeFileSync(target, text);
    console.log(`brief: wrote ${target} (${brief.shots.length} shots)`);
  }
}
